import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  Grid,
  Paper,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';
import {
  CloudDone as ConnectedIcon,
  CloudOff as DisconnectedIcon,
  Refresh as RefreshIcon,
} from '@mui/icons-material';
import axios from 'axios';
import AdminPortalLayout from './AdminPortalLayout';
import { buildApiUrl } from '../../config/apiConfig';
import { useWebSocket } from '../../context/WebSocketContext';
import ScrollableTableContainer from '../shared/ScrollableTableContainer';

interface OrchestrationEvent {
  id?: string;
  type?: string;
  source?: string;
  timestamp?: string;
  msmeId?: string;
  payload?: Record<string, unknown>;
}

interface SystemHealthPayload {
  timestamp: string;
  uptimeSeconds: number;
  socketIo: string;
  orchestration: {
    totalEvents: number;
    lastEvent: OrchestrationEvent | null;
    recentEvents: OrchestrationEvent[];
    multiAgentStatus?: Record<string, unknown>;
  };
  monitoring?: Record<string, unknown>;
  aiAgents?: { status?: string; agentCount?: number };
}

const formatTimestamp = (value?: string) => {
  if (!value) return '—';
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? value : parsed.toLocaleString('en-IN');
};

const AdminSystemHealthDashboard: React.FC = () => {
  const { connected, on, off } = useWebSocket();
  const [health, setHealth] = useState<SystemHealthPayload | null>(null);
  const [liveEvents, setLiveEvents] = useState<OrchestrationEvent[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const loadHealth = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get(buildApiUrl('/admin/system-health'), {
        headers: token ? { Authorization: `Bearer ${token}` } : undefined,
        params: { limit: 40 },
      });
      const payload = response.data?.data as SystemHealthPayload;
      setHealth(payload);
      setLiveEvents(payload?.orchestration?.recentEvents || []);
    } catch (loadError) {
      setError(loadError instanceof Error ? loadError.message : 'Unable to load system health.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void loadHealth();
  }, [loadHealth]);

  useEffect(() => {
    const handleOrchestrationEvent = (event: OrchestrationEvent) => {
      setLiveEvents((current) => [event, ...current].slice(0, 50));
    };

    on('orchestration:event', handleOrchestrationEvent);
    return () => {
      off('orchestration:event', handleOrchestrationEvent);
    };
  }, [on, off]);

  const agentStatus = health?.aiAgents?.status || 'unknown';
  const agentCount = health?.aiAgents?.agentCount;

  return (
    <AdminPortalLayout
      title="System health"
      subtitle="Monitor orchestration events, agent runtime, and platform dependencies (admin only)."
    >
      <Stack direction="row" spacing={1} sx={{ mb: 2 }} alignItems="center" flexWrap="wrap" useFlexGap>
        <Button
          variant="outlined"
          size="small"
          startIcon={loading ? <CircularProgress size={14} /> : <RefreshIcon />}
          onClick={() => void loadHealth()}
          disabled={loading}
        >
          Refresh
        </Button>
        <Chip
          size="small"
          icon={connected ? <ConnectedIcon /> : <DisconnectedIcon />}
          label={connected ? 'WebSocket connected' : 'WebSocket disconnected'}
          color={connected ? 'success' : 'default'}
          variant="outlined"
        />
        {health?.socketIo && (
          <Chip size="small" variant="outlined" label={`Socket.IO: ${health.socketIo}`} />
        )}
      </Stack>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>
          {error}
        </Alert>
      )}

      {loading && !health ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 6 }}>
          <CircularProgress />
        </Box>
      ) : (
        <>
          <Grid container spacing={2} sx={{ mb: 3 }}>
            <Grid item xs={12} sm={6} md={3}>
              <Card>
                <CardContent>
                  <Typography variant="body2" color="text.secondary">
                    Uptime
                  </Typography>
                  <Typography variant="h5">
                    {health ? `${Math.floor(health.uptimeSeconds / 60)} min` : '—'}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={12} sm={6} md={3}>
              <Card>
                <CardContent>
                  <Typography variant="body2" color="text.secondary">
                    AI agents
                  </Typography>
                  <Typography variant="h5">{agentStatus}</Typography>
                  {typeof agentCount === 'number' && (
                    <Typography variant="caption" color="text.secondary">
                      {agentCount} registered
                    </Typography>
                  )}
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={12} sm={6} md={3}>
              <Card>
                <CardContent>
                  <Typography variant="body2" color="text.secondary">
                    Orchestration events
                  </Typography>
                  <Typography variant="h5">{health?.orchestration?.totalEvents ?? 0}</Typography>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={12} sm={6} md={3}>
              <Card>
                <CardContent>
                  <Typography variant="body2" color="text.secondary">
                    Last event
                  </Typography>
                  <Typography variant="body1" sx={{ fontWeight: 600 }}>
                    {health?.orchestration?.lastEvent?.type || '—'}
                  </Typography>
                  <Typography variant="caption" color="text.secondary">
                    {formatTimestamp(health?.orchestration?.lastEvent?.timestamp)}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          </Grid>

          <Paper sx={{ p: 2, mb: 3 }}>
            <Typography variant="h6" sx={{ mb: 1 }}>
              Live orchestration feed
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
              Events stream over Socket.IO (`orchestration:event`) and are retained in the orchestration manager bus.
            </Typography>
            <ScrollableTableContainer>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>Time</TableCell>
                    <TableCell>Type</TableCell>
                    <TableCell>Source</TableCell>
                    <TableCell>MSME</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {liveEvents.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={4}>
                        <Typography variant="body2" color="text.secondary">
                          No orchestration events recorded yet.
                        </Typography>
                      </TableCell>
                    </TableRow>
                  ) : (
                    liveEvents.map((event, index) => (
                      <TableRow key={event.id || `${event.type}-${event.timestamp}-${index}`} hover>
                        <TableCell>{formatTimestamp(event.timestamp)}</TableCell>
                        <TableCell>{event.type || '—'}</TableCell>
                        <TableCell>{event.source || '—'}</TableCell>
                        <TableCell>{event.msmeId ? String(event.msmeId) : '—'}</TableCell>
                      </TableRow>
                    ))
                  )}
                </TableBody>
              </Table>
            </ScrollableTableContainer>
          </Paper>

          {health?.orchestration?.multiAgentStatus && (
            <Paper sx={{ p: 2 }}>
              <Typography variant="h6" sx={{ mb: 1 }}>
                Multi-agent runtime
              </Typography>
              <Box
                component="pre"
                sx={{
                  m: 0,
                  p: 2,
                  bgcolor: 'grey.100',
                  borderRadius: 1,
                  overflow: 'auto',
                  fontSize: 12,
                  maxHeight: 320,
                }}
              >
                {JSON.stringify(health.orchestration.multiAgentStatus, null, 2)}
              </Box>
            </Paper>
          )}
        </>
      )}
    </AdminPortalLayout>
  );
};

export default AdminSystemHealthDashboard;
